INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q120998541', 'Invasion of Surinam', 'The Invasion of Surinam was a Dutch attempt to capture the English held colony of Surinam in February 1667. The Dutch under the command of Abraham Crijnssen captured the colony without much resistance.', 1667, 2, 25, 1667, 2, 27, 'day', '25 February 1667 – 27 February 1667', 26, 'https://en.wikipedia.org/wiki/Invasion_of_Surinam_(1667)'),
  ('Q593085', 'Battle of Suriname', 'The invasion of Surinam was a British military campaign which resulted in the capture and occupation of the Dutch colony of Surinam in 1804 during the Napoleonic Wars. Surinam, defended by a weak Batavian garrison under the command of Abraham Jacob van Imbijze van Batenburg, was attacked by a British expeditionary force led by Samuel Hood and Sir Charles Green on 25 April.', 1804, 5, 5, NULL, NULL, NULL, 'day', '5 May 1804', 39, 'https://en.wikipedia.org/wiki/Invasion_of_Surinam_(1804)'),
  ('Q967981', '1980 Surinamese coup d''état', 'The 1980 Surinamese coup d''état, usually referred to as the Sergeants'' Coup (Dutch: De Sergeantencoup), was a military coup in Suriname which occurred on 25 February 1980, when a group of 16 sergeants (Dutch: groep van zestien, lit. ''group of sixteen'') of the Surinamese Armed Forces (SKM) led by Dési Bouterse overthrew the government of Prime Minister Henck Arron with a violent coup d''état. This marked the beginning of the military dictatorship that dominated the country from 1980 until 1991.', 1980, 2, 25, NULL, NULL, NULL, 'day', '25 February 1980', 43, 'https://en.wikipedia.org/wiki/1980_Surinamese_coup_d''%C3%A9tat'),
  ('Q1915188', 'Surinamese Interior War', 'The Surinamese Civil War, also known as Surinamese Interior War (Dutch: Binnenlandse Oorlog), was a civil war fought in eastern Suriname between 1986 and 1992. The conflict primarily involved the Jungle Commando, a rebel group composed largely of Saramaka (Maroon) fighters and led by former soldier Ronnie Brunswijk, and the Surinamese National Army, commanded by then-army chief and de facto head of state Dési Bouterse.', 1986, 11, NULL, 1992, NULL, NULL, 'month', 'November 1986 – 1992', 51, 'https://en.wikipedia.org/wiki/Surinamese_Civil_War'),
  ('Q2134739', 'Moiwana massacre', 'The Moiwana Massacre was a massacre perpetrated by the Suriname National Army on the Maroon village of Moiwana on 29 November 1986. The massacre occurred during the Surinamese Interior War between the national army led by Dési Bouterse and the Jungle Commando led by Ronnie Brunswijk.', 1986, 11, 29, NULL, NULL, NULL, 'day', '29 November 1986', 43, 'https://en.wikipedia.org/wiki/Moiwana_massacre'),
  ('Q2610182', 'Surinam Airways Flight 764', 'Surinam Airways Flight 764 was an international scheduled passenger flight of Surinam Airways from Amsterdam Airport Schiphol in the Netherlands to Paramaribo-Zanderij International Airport in Suriname. On 7 June 1989, the DC-8-62 serving the flight crashed during approach to Paramaribo-Zanderij, killing 178 of the 187 on board.', 1989, 6, 7, NULL, NULL, NULL, 'day', '7 June 1989', 52, 'https://en.wikipedia.org/wiki/Surinam_Airways_Flight_764'),
  ('Q14466700', '1990 Surinamese coup d''état', 'The 1990 Surinamese coup d''état, usually referred to as the Telephone Coup (Dutch: De Telefooncoup), was a military coup in Suriname on 24 December 1990. The coup was carried out by the acting commander-in-chief of the Suriname National Army (SNL), Police Chief Ivan Graanoogst.', 1990, 12, 24, NULL, NULL, NULL, 'day', '24 December 1990', 37, 'https://en.wikipedia.org/wiki/1990_Surinamese_coup_d''%C3%A9tat'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q111263881', 'March 2022 Suriname flooding', 'The 2022 Suriname floods were a series of floods that occurred in March 2022. They primarily affected Indigenous and Maroon settlement areas in the eastern part of Suriname.', 2022, 3, NULL, NULL, NULL, NULL, 'month', 'March 2022', 34, 'https://en.wikipedia.org/wiki/2022_Suriname_floods');

